        titles=re.findall(r'<title[^>]*>(.*?)</title>', c)
        print(url, '->', len(titles))
        for t in titles[:25]: print('   ', t.strip()[:120])
        break
    except Exception as e:
        print(url, 'ERR', getattr(e,'code',e))
"

